//! Acceptance tests of Chapter 12.6 (`eigsh`, `eigs`, shift-invert), task
//! L3.4, and criterion (iii) of Chapter 12.5 (`svds`, moved from L3.3), as
//! ratified (D-0127, S9; D-0134):
//!
//! (a) on Matrix Market matrices the `k` wanted eigenvalues agree with
//!     ARPACK (`scipy.sparse.linalg.eigsh`/`eigs`, fixtures in `tests/data`,
//!     generated by `make_fixtures.py`) to `1e-10` relative where the gap to
//!     the rest of the spectrum is `≥ 10⁻⁶‖A‖`, and the wanted *set* is
//!     ARPACK's (every value of ours is matched);
//! (b) every returned pair — the shift-invert ones included, on the
//!     original `A` (Algorithm R of Chapter 12.6.2) — has `‖Ay − θy‖ ≤ (τ + c_K·ncv·u)·‖A‖` (`τ = ε`
//!     for `tol = 0`; with `tol = 1e-10` the literal `≤ tol·‖A‖` is checked
//!     too — question Q-L34-2);
//! (c) `count_below` equals the dense count;
//! (d) `svds` agrees with `scipy.sparse.linalg.svds` to `1e-10` relative on
//!     the `σ_i ≥ 10⁻³σ_1` whose gap is `≥ 10⁻⁶σ_1`;
//! (e) `DoubleDouble` smoke tests of `eigsh`, `eigs` and `eigsh_near`.
//!
//! Every table line is printed with `--nocapture`.

#![allow(
    clippy::cast_precision_loss,
    clippy::float_cmp,
    clippy::too_many_lines,
    clippy::needless_range_loop,
    clippy::cast_possible_truncation,
    clippy::cast_sign_loss
)]

mod support;

use std::time::Instant;

use support::mm::{Ref, read_mm};
use xingo_extprec::DoubleDouble as Dd;
use xingo_sparse::{Col, CscMatrix};
use xingo_statla::{
    Complex, EigsOptions, LinearOperator, SvdsOptions, Which, eigs, eigs_near, eigsh, eigsh_near,
    svds,
};

/// Runs whose wanted values are *interior* (smallest magnitude of an
/// indefinite or complex spectrum): not "extreme eigenvalues", so outside
/// criterion (a); without shift-invert neither ARPACK nor Krylov–Schur is
/// reliable there (ARPACK itself, with another start vector, stops at 4 of
/// 6 after 3001 iterations on `symrand_300 SM`). They are run with
/// `allow_partial` and reported only.
const INTERIOR: [(&str, &str); 2] = [("symrand_300", "SM"), ("nonsymrand_200", "SI")];

/// `c_K` of the residual guarantee (Chapter 12.6; measured, with a margin).
const C_K: f64 = 8.0;
/// The same constant for the double-double smoke tests: its operations
/// round to a few units of `u = 2⁻¹⁰⁵`, not to half an ulp, and the
/// measured ratios are larger (`≤ 19.4` against `≤ 2.5` in `f64`).
const C_K_DD: f64 = 64.0;
/// Criterion (a).
const REL: f64 = 1e-10;
/// Gap condition of (a), relative to ‖A‖, and of (d), relative to σ₁.
const GAP: f64 = 1e-6;

const SYM: [&str; 3] = ["lap2d_20x17", "symrand_300", "tridiag_graded_200"];
const GEN: [&str; 2] = ["convdiff_20x20", "nonsymrand_200"];

fn default_ncv(n: usize, k: usize) -> usize {
    n.min((2 * k + 1).max(20))
}

/// `‖A y − θ y‖` for a complex pair, in double-double (the evaluation
/// error is then far below what is measured).
fn residual(a: &CscMatrix<f64>, yr: &[f64], yi: &[f64], th: Complex<f64>) -> f64 {
    let n = a.n_rows();
    let (mut ar, mut ai) = (vec![Dd::ZERO; n], vec![Dd::ZERO; n]);
    for j in 0..a.n_cols() {
        let (rows, vals) = a.col(Col::from_usize(j));
        for (&i, &v) in rows.iter().zip(vals) {
            let v = Dd::from_f64(v);
            ar[i as usize] += v * Dd::from_f64(yr[j]);
            ai[i as usize] += v * Dd::from_f64(yi[j]);
        }
    }
    let (tr, ti) = (Dd::from_f64(th.re), Dd::from_f64(th.im));
    let mut s = Dd::ZERO;
    for i in 0..n {
        let (yr, yi) = (Dd::from_f64(yr[i]), Dd::from_f64(yi[i]));
        let er = ar[i] - (tr * yr - ti * yi);
        let ei = ai[i] - (tr * yi + ti * yr);
        s += er * er + ei * ei;
    }
    s.sqrt().to_f64()
}

/// Distance from `z` to the nearest *other* eigenvalue of `spec` (the
/// nearest one is taken as `z` itself).
fn gap(spec: &[(f64, f64)], z: (f64, f64)) -> f64 {
    let d = |w: &(f64, f64)| (w.0 - z.0).hypot(w.1 - z.1);
    let me = (0..spec.len())
        .min_by(|&i, &j| d(&spec[i]).total_cmp(&d(&spec[j])))
        .unwrap();
    spec.iter()
        .enumerate()
        .filter(|&(i, _)| i != me)
        .map(|(_, w)| d(w))
        .fold(f64::INFINITY, f64::min)
}

/// One comparison against ARPACK: for every value of ours the nearest
/// ARPACK value (conjugates included); returns `(max rel error over the
/// gapped values, number compared, number skipped)`.
fn compare(
    ours: &[Complex<f64>],
    arpack: &[(f64, f64)],
    spec: &[(f64, f64)],
    anorm: f64,
    what: &str,
) -> (f64, usize, usize) {
    let mut ar: Vec<(f64, f64)> = arpack.to_vec();
    ar.extend(arpack.iter().map(|&(r, i)| (r, -i)));
    let (mut worst, mut n_cmp, mut n_skip) = (0.0f64, 0, 0);
    for th in ours {
        let near = ar
            .iter()
            .min_by(|a, b| {
                (a.0 - th.re)
                    .hypot(a.1 - th.im)
                    .total_cmp(&(b.0 - th.re).hypot(b.1 - th.im))
            })
            .unwrap();
        let err = (near.0 - th.re).hypot(near.1 - th.im) / near.0.hypot(near.1);
        if gap(spec, *near) >= GAP * anorm {
            worst = worst.max(err);
            n_cmp += 1;
            assert!(
                err <= REL,
                "{what}: θ = {th:?}, ARPACK {near:?}, rel {err:e}"
            );
        } else {
            n_skip += 1;
        }
    }
    (worst, n_cmp, n_skip)
}

fn print_row(
    name: &str,
    what: &str,
    cmp: (f64, usize, usize),
    res: f64,
    restarts: usize,
    applies: usize,
    ms: f64,
) {
    eprintln!(
        "| {name} | {what} | {:.1e} | {}/{} | {res:.2} | {restarts} | {applies} | {ms:.1} |",
        cmp.0,
        cmp.1,
        cmp.1 + cmp.2
    );
}

/// (a), (b), (c) on the symmetric matrices.
#[test]
fn eigsh_matches_arpack() {
    let u = f64::EPSILON / 2.0;
    let tau = f64::EPSILON;
    let mut worst_res = 0.0f64;
    eprintln!(
        "| matrix | run | max rel err vs ARPACK | compared | (‖r‖/‖A‖ − τ)/(ncv u) | restarts | applies | ms |"
    );
    eprintln!("|---|---|---:|---:|---:|---:|---:|---:|");
    for name in SYM {
        let mm = read_mm(name);
        let r = Ref::read(name);
        let a = mm.a;
        let n = a.n_rows();
        let anorm = r.values("norm2").unwrap()[0];
        let dense = r.values("dense").unwrap();
        let spec: Vec<(f64, f64)> = dense.iter().map(|&x| (x, 0.0)).collect();
        let check = |vals: &[f64], vecs: &xingo_statla::DenseBlock<f64>, ncv: usize, what: &str| {
            let mut w = 0.0f64;
            for (c, &th) in vals.iter().enumerate() {
                let y = &vecs.data[c * n..(c + 1) * n];
                let res = residual(&a, y, &vec![0.0; n], Complex { re: th, im: 0.0 });
                let ratio = (res / anorm - tau) / (ncv as f64 * u);
                assert!(
                    ratio <= C_K,
                    "{name} {what} {c}: ‖r‖ = {res:e}, ratio {ratio}"
                );
                w = w.max(ratio);
            }
            w
        };
        for (tag, k, vals) in r.tagged("eigsh") {
            let which = Which::from_arpack(&tag).unwrap();
            if INTERIOR.contains(&(name, tag.as_str())) {
                let o = EigsOptions {
                    allow_partial: true,
                    ..EigsOptions::default()
                };
                let f = eigsh(&mut a.clone(), k, which, &o).unwrap();
                eprintln!(
                    "| {name} | eigsh {tag} (interior, excluded) | — | {}/{k} converged | — | {} | {} | — |",
                    f.values.len(),
                    f.stats.restarts,
                    f.stats.applies
                );
                continue;
            }
            let t0 = Instant::now();
            let f = eigsh(&mut a.clone(), k, which, &EigsOptions::default()).unwrap();
            let ms = t0.elapsed().as_secs_f64() * 1e3;
            assert_eq!(f.values.len(), k);
            let ours: Vec<Complex<f64>> =
                f.values.iter().map(|&re| Complex { re, im: 0.0 }).collect();
            let arp: Vec<(f64, f64)> = vals.iter().map(|&x| (x, 0.0)).collect();
            let cmp = compare(&ours, &arp, &spec, anorm, &format!("{name} eigsh {tag}"));
            let res = check(
                &f.values,
                f.vectors.as_ref().unwrap(),
                default_ncv(n, k),
                &tag,
            );
            worst_res = worst_res.max(res);
            print_row(
                name,
                &format!("eigsh {tag}"),
                cmp,
                res,
                f.stats.restarts,
                f.stats.applies,
                ms,
            );
        }
        for (tag, k, vals) in r.tagged("eigsh_near") {
            let sigma: f64 = tag.parse().unwrap();
            let t0 = Instant::now();
            let (f, below) = eigsh_near(&a, k, sigma, &EigsOptions::default()).unwrap();
            let ms = t0.elapsed().as_secs_f64() * 1e3;
            // (c).
            assert_eq!(
                below,
                dense.iter().filter(|&&x| x < sigma).count(),
                "{name} σ = {sigma}"
            );
            let ours: Vec<Complex<f64>> =
                f.values.iter().map(|&re| Complex { re, im: 0.0 }).collect();
            let arp: Vec<(f64, f64)> = vals.iter().map(|&x| (x, 0.0)).collect();
            let cmp = compare(
                &ours,
                &arp,
                &spec,
                anorm,
                &format!("{name} eigsh_near {sigma}"),
            );
            // The residual on the original A: criterion (b), as for `eigsh`,
            // thanks to the refinement step of the solves (Algorithm R).
            let mut res = 0.0f64;
            let y = f.vectors.as_ref().unwrap();
            for (c, &th) in f.values.iter().enumerate() {
                let rr = residual(
                    &a,
                    &y.data[c * n..(c + 1) * n],
                    &vec![0.0; n],
                    Complex { re: th, im: 0.0 },
                );
                let ratio = (rr / anorm - tau) / (default_ncv(n, k) as f64 * u);
                assert!(
                    ratio <= C_K,
                    "{name} near {sigma} {c}: ‖r‖ = {rr:e}, ratio {ratio}"
                );
                assert!(rr <= 1e-10 * anorm, "{name} near {sigma} {c}: ‖r‖ = {rr:e}");
                res = res.max(ratio);
            }
            print_row(
                name,
                &format!("eigsh_near σ={sigma} (below {below})"),
                cmp,
                res,
                f.stats.restarts,
                f.stats.applies,
                ms,
            );
        }
        // (b) literally, with tol = 1e-10.
        let o = EigsOptions {
            tol: 1e-10,
            ..EigsOptions::default()
        };
        let f = eigsh(&mut a.clone(), 6, Which::LargestAlgebraic, &o).unwrap();
        let y = f.vectors.as_ref().unwrap();
        for (c, &th) in f.values.iter().enumerate() {
            let res = residual(
                &a,
                &y.data[c * n..(c + 1) * n],
                &vec![0.0; n],
                Complex { re: th, im: 0.0 },
            );
            assert!(res <= 1e-10 * anorm, "{name} tol 1e-10: {res:e}");
        }
    }
    eprintln!("worst residual ratio (eigsh): {worst_res:.3}");
}

/// (a), (b) on the general matrices.
#[test]
fn eigs_matches_arpack() {
    let u = f64::EPSILON / 2.0;
    let tau = f64::EPSILON;
    let mut worst_res = 0.0f64;
    eprintln!(
        "| matrix | run | max rel err vs ARPACK | compared | (‖r‖/‖A‖ − τ)/(ncv u) | restarts | applies | ms |"
    );
    eprintln!("|---|---|---:|---:|---:|---:|---:|---:|");
    for name in GEN {
        let mm = read_mm(name);
        let r = Ref::read(name);
        let a = mm.a;
        let n = a.n_rows();
        let anorm = r.values("norm2").unwrap()[0];
        let (dre, dim) = (r.values("dense_re").unwrap(), r.values("dense_im").unwrap());
        let spec: Vec<(f64, f64)> = dre.iter().zip(&dim).map(|(&x, &y)| (x, y)).collect();
        let pairs = |v: &[f64]| -> Vec<(f64, f64)> { v.chunks(2).map(|c| (c[0], c[1])).collect() };
        let check = |f: &xingo_statla::Eigen<f64>, ncv: usize, what: &str| {
            let (yr, yi) = (
                f.vectors_re.as_ref().unwrap(),
                f.vectors_im.as_ref().unwrap(),
            );
            let mut w = 0.0f64;
            for (c, th) in f.values.iter().enumerate() {
                let res = residual(
                    &a,
                    &yr.data[c * n..(c + 1) * n],
                    &yi.data[c * n..(c + 1) * n],
                    *th,
                );
                let ratio = (res / anorm - tau) / (ncv as f64 * u);
                // Shift-invert included: the refinement step of the solves
                // (Algorithm R) makes the residual on A follow criterion (b).
                assert!(
                    ratio <= C_K,
                    "{name} {what} {c}: ‖r‖ = {res:e}, ratio {ratio}"
                );
                assert!(res <= 1e-10 * anorm, "{name} {what} {c}: ‖r‖ = {res:e}");
                w = w.max(ratio);
            }
            w
        };
        for (tag, k, vals) in r.tagged("eigs") {
            let which = Which::from_arpack(&tag).unwrap();
            if INTERIOR.contains(&(name, tag.as_str())) {
                let o = EigsOptions {
                    allow_partial: true,
                    ..EigsOptions::default()
                };
                let f = eigs(&mut a.clone(), k, which, &o).unwrap();
                eprintln!(
                    "| {name} | eigs {tag} (interior, excluded) | — | {}/{k} converged | — | {} | {} | — |",
                    f.values.len(),
                    f.stats.restarts,
                    f.stats.applies
                );
                continue;
            }
            let t0 = Instant::now();
            let f = eigs(&mut a.clone(), k, which, &EigsOptions::default()).unwrap();
            let ms = t0.elapsed().as_secs_f64() * 1e3;
            assert_eq!(f.values.len(), k);
            let cmp = compare(
                &f.values,
                &pairs(&vals),
                &spec,
                anorm,
                &format!("{name} eigs {tag}"),
            );
            let res = check(&f, default_ncv(n, k), &tag);
            worst_res = worst_res.max(res);
            print_row(
                name,
                &format!("eigs {tag}"),
                cmp,
                res,
                f.stats.restarts,
                f.stats.applies,
                ms,
            );
        }
        for (tag, k, vals) in r.tagged("eigs_near") {
            let sigma: f64 = tag.parse().unwrap();
            let t0 = Instant::now();
            let f = eigs_near(&a, k, sigma, &EigsOptions::default()).unwrap();
            let ms = t0.elapsed().as_secs_f64() * 1e3;
            let cmp = compare(
                &f.values,
                &pairs(&vals),
                &spec,
                anorm,
                &format!("{name} eigs_near {sigma}"),
            );
            let res = check(&f, default_ncv(n, k), "near");
            for w in f.values.windows(2) {
                assert!(
                    w[0].im >= 0.0 || w[1].im != -w[0].im,
                    "{name}: pair order {:?}",
                    f.values
                );
            }
            print_row(
                name,
                &format!("eigs_near σ={sigma}"),
                cmp,
                res,
                f.stats.restarts,
                f.stats.applies,
                ms,
            );
        }
    }
    eprintln!("worst residual ratio (eigs): {worst_res:.3}");
}

/// (d): `svds` against `scipy.sparse.linalg.svds` on every fixture matrix.
#[test]
fn svds_matches_scipy() {
    eprintln!("| matrix | max rel err vs scipy.svds | compared | max rel err vs dense | ms |");
    eprintln!("|---|---:|---:|---:|---:|");
    for name in SYM.iter().chain(&GEN).chain(&["rectrand_300x200"]) {
        let mm = read_mm(name);
        let r = Ref::read(name);
        let mut a = mm.a;
        let sv = r.values("sv_dense").unwrap();
        let s1 = sv[0];
        let rec = r.values("svds").unwrap();
        let (k, sc) = (rec[0] as usize, rec[1..].to_vec());
        let t0 = Instant::now();
        let f = svds(&mut a, k, &SvdsOptions::default()).unwrap();
        let ms = t0.elapsed().as_secs_f64() * 1e3;
        let (mut worst, mut worst_dense, mut n_cmp) = (0.0f64, 0.0f64, 0);
        for (i, (&ours, &theirs)) in f.s.iter().zip(&sc).enumerate() {
            let g = sv
                .iter()
                .enumerate()
                .filter(|&(j, _)| j != i)
                .map(|(_, &s)| (s - sv[i]).abs())
                .fold(f64::INFINITY, f64::min);
            worst_dense = worst_dense.max((ours - sv[i]).abs() / s1);
            if theirs >= 1e-3 * s1 && g >= GAP * s1 {
                let e = (ours - theirs).abs() / theirs;
                assert!(e <= REL, "{name} σ_{i}: {ours} vs {theirs}");
                worst = worst.max(e);
                n_cmp += 1;
            }
        }
        eprintln!("| {name} | {worst:.1e} | {n_cmp}/{k} | {worst_dense:.1e} | {ms:.1} |");
    }
}

/// The matrix in double-double (exact conversion).
fn to_dd(a: &CscMatrix<f64>) -> CscMatrix<Dd> {
    CscMatrix {
        n_rows: a.n_rows,
        col_ptr: a.col_ptr.clone(),
        row_idx: a.row_idx.clone(),
        val: a.val.iter().map(|&v| Dd::from_f64(v)).collect(),
    }
}

fn residual_dd(a: &mut CscMatrix<Dd>, yr: &[Dd], yi: &[Dd], th: Complex<Dd>) -> f64 {
    let n = a.n_rows();
    let (mut ar, mut ai) = (vec![Dd::ZERO; n], vec![Dd::ZERO; n]);
    a.apply(yr, &mut ar).unwrap();
    a.apply(yi, &mut ai).unwrap();
    let mut s = Dd::ZERO;
    for i in 0..n {
        let er = ar[i] - (th.re * yr[i] - th.im * yi[i]);
        let ei = ai[i] - (th.re * yi[i] + th.im * yr[i]);
        s += er * er + ei * ei;
    }
    s.sqrt().to_f64()
}

/// (e): `DoubleDouble` smoke tests — the values agree with the f64 dense
/// spectrum, the residuals are at the double-double level.
#[test]
fn double_double_smoke() {
    let udd = Dd::EPSILON.to_f64() / 2.0;
    // eigsh on the graded tridiagonal.
    let name = "tridiag_graded_200";
    let a = read_mm(name).a;
    let r = Ref::read(name);
    let anorm = r.values("norm2").unwrap()[0];
    let dense = r.values("dense").unwrap();
    let mut ad = to_dd(&a);
    let n = a.n_rows();
    let f = eigsh(&mut ad, 4, Which::LargestAlgebraic, &EigsOptions::default()).unwrap();
    let y = f.vectors.as_ref().unwrap();
    let zero = vec![Dd::ZERO; n];
    for (c, th) in f.values.iter().enumerate() {
        assert!(
            (th.to_f64() - dense[n - 1 - c]).abs() <= 1e-13 * anorm,
            "{th:?}"
        );
        let res = residual_dd(
            &mut ad,
            &y.data[c * n..(c + 1) * n],
            &zero,
            Complex {
                re: *th,
                im: Dd::ZERO,
            },
        );
        let ratio = (res / anorm - 2.0 * udd) / (20.0 * udd);
        eprintln!("dd eigsh {c}: residual ratio {ratio:.3}");
        assert!(ratio <= C_K_DD, "{ratio}");
    }
    // eigsh_near in double-double (SupernodalLdl<Dd>), with count_below.
    let (g, below) = eigsh_near(&to_dd(&a), 3, Dd::from_f64(3.0), &EigsOptions::default()).unwrap();
    assert_eq!(below, dense.iter().filter(|&&x| x < 3.0).count());
    let mut near = dense.clone();
    near.sort_by(|x, y| (x - 3.0).abs().total_cmp(&(y - 3.0).abs()));
    for (th, e) in g.values.iter().zip(&near) {
        assert!((th.to_f64() - e).abs() <= 1e-13 * anorm, "{th:?} {e}");
    }
    // eigs on the random nonsymmetric matrix.
    let name = "nonsymrand_200";
    let a = read_mm(name).a;
    let r = Ref::read(name);
    let anorm = r.values("norm2").unwrap()[0];
    let n = a.n_rows();
    let mut ad = to_dd(&a);
    let f = eigs(&mut ad, 4, Which::LargestMagnitude, &EigsOptions::default()).unwrap();
    let ours64 = eigs(
        &mut a.clone(),
        4,
        Which::LargestMagnitude,
        &EigsOptions::default(),
    )
    .unwrap();
    let (yr, yi) = (
        f.vectors_re.as_ref().unwrap(),
        f.vectors_im.as_ref().unwrap(),
    );
    for (c, th) in f.values.iter().enumerate() {
        let t64 = ours64.values[c];
        assert!(
            (th.re.to_f64() - t64.re).hypot(th.im.to_f64() - t64.im) <= 1e-12 * anorm,
            "{th:?} {t64:?}"
        );
        let res = residual_dd(
            &mut ad,
            &yr.data[c * n..(c + 1) * n],
            &yi.data[c * n..(c + 1) * n],
            *th,
        );
        let ratio = (res / anorm - 2.0 * udd) / (20.0 * udd);
        eprintln!("dd eigs {c}: residual ratio {ratio:.3}");
        assert!(ratio <= C_K_DD, "{ratio}");
    }
}

/// Algorithm R of Chapter 12.6.2: every application of a shift-invert
/// operator is backward stable to the working precision, `η = ‖x − M y‖_∞ /
/// (‖M‖_∞ ‖y‖_∞) ≤ 2u` (`M = A − σI`, the residual in double-double) —
/// without the refinement step the threshold LU and the Bunch–Kaufman
/// `LBLᵀ` leave the growth of the factorization in `η`.
#[test]
fn shift_invert_solves_are_backward_stable() {
    use xingo_sparse::LuOptions;
    use xingo_statla::{ShiftInvert, SymShiftInvert};
    let u = f64::EPSILON / 2.0;
    let eta = |a: &CscMatrix<f64>, sigma: f64, x: &[f64], y: &[f64]| {
        let n = a.n_rows();
        let mut r: Vec<Dd> = x.iter().map(|&v| Dd::from_f64(v)).collect();
        let mut rows_abs = vec![0.0f64; n];
        for j in 0..n {
            let (rows, vals) = a.col(Col::from_usize(j));
            let mut diag = false;
            for (&i, &v) in rows.iter().zip(vals) {
                let i = i as usize;
                let v = if i == j {
                    diag = true;
                    v - sigma
                } else {
                    v
                };
                r[i] -= Dd::from_f64(v) * Dd::from_f64(y[j]);
                rows_abs[i] += v.abs();
            }
            if !diag {
                r[j] += Dd::from_f64(sigma) * Dd::from_f64(y[j]);
                rows_abs[j] += sigma.abs();
            }
        }
        let rn = r.iter().map(|v| v.to_f64().abs()).fold(0.0, f64::max);
        let mn = rows_abs.iter().copied().fold(0.0, f64::max);
        let yn = y.iter().map(|v| v.abs()).fold(0.0, f64::max);
        rn / (mn * yn)
    };
    let mut rng = support::Rng::new(3);
    for (name, sigma) in [
        ("symrand_300", 0.0),
        ("lap2d_20x17", 1.05),
        ("tridiag_graded_200", 3.0),
    ] {
        let a = read_mm(name).a;
        let n = a.n_rows();
        let mut op = SymShiftInvert::<f64>::new(&a, sigma, xingo_sparse::NaiveDense).unwrap();
        let mut worst = 0.0f64;
        for _ in 0..5 {
            let x = rng.gauss_vec(n);
            let mut y = vec![0.0; n];
            op.apply(&x, &mut y).unwrap();
            worst = worst.max(eta(&a, sigma, &x, &y) / u);
        }
        eprintln!("SymShiftInvert {name} σ = {sigma}: η/u = {worst:.3}");
        assert!(worst <= 2.0, "{name}: η = {worst} u");
    }
    for (name, sigma) in [
        ("nonsymrand_200", -0.5),
        ("nonsymrand_200", 0.25),
        ("convdiff_20x20", 4.0),
    ] {
        let a = read_mm(name).a;
        let n = a.n_rows();
        let mut op = ShiftInvert::new(&a, sigma, LuOptions::default()).unwrap();
        let mut worst = 0.0f64;
        for _ in 0..5 {
            let x = rng.gauss_vec(n);
            let mut y = vec![0.0; n];
            op.apply(&x, &mut y).unwrap();
            worst = worst.max(eta(&a, sigma, &x, &y) / u);
        }
        eprintln!("ShiftInvert {name} σ = {sigma}: η/u = {worst:.3}");
        assert!(worst <= 2.0, "{name}: η = {worst} u");
    }
}

/// (e), continued: `eigs_near` in `DoubleDouble` (`Lu<Dd>` with
/// `LuOptions::for_scalar::<Dd>()`, Algorithm R in double-double) on the
/// random nonsymmetric matrix, `σ = 0.25` (issue xingo-statla#7): the
/// values agree with the `f64` run and with ARPACK, the residuals on `A`
/// are at the double-double level.
#[test]
fn double_double_eigs_near_smoke() {
    let udd = Dd::EPSILON.to_f64() / 2.0;
    let name = "nonsymrand_200";
    let a = read_mm(name).a;
    let r = Ref::read(name);
    let anorm = r.values("norm2").unwrap()[0];
    let n = a.n_rows();
    let (sigma, k) = (0.25, 4);
    let f64_run = eigs_near(&a, k, sigma, &EigsOptions::default()).unwrap();
    let mut ad = to_dd(&a);
    let f = eigs_near(&ad, k, Dd::from_f64(sigma), &EigsOptions::default()).unwrap();
    assert_eq!(f.values.len(), k);
    let arpack: Vec<(f64, f64)> = r
        .tagged("eigs_near")
        .into_iter()
        .find(|(tag, _, _)| tag.parse::<f64>().unwrap() == sigma)
        .map(|(_, _, v)| v.chunks(2).map(|c| (c[0], c[1])).collect())
        .unwrap();
    let (yr, yi) = (
        f.vectors_re.as_ref().unwrap(),
        f.vectors_im.as_ref().unwrap(),
    );
    for (c, th) in f.values.iter().enumerate() {
        let t64 = f64_run.values[c];
        let (re, im) = (th.re.to_f64(), th.im.to_f64());
        assert!(
            (re - t64.re).hypot(im - t64.im) <= 1e-12 * anorm,
            "{th:?} {t64:?}"
        );
        let near = arpack
            .iter()
            .flat_map(|&(x, y)| [(x, y), (x, -y)])
            .map(|(x, y)| (x - re).hypot(y - im))
            .fold(f64::INFINITY, f64::min);
        assert!(near <= 1e-10 * anorm, "{th:?}: ARPACK at {near:e}");
        let res = residual_dd(
            &mut ad,
            &yr.data[c * n..(c + 1) * n],
            &yi.data[c * n..(c + 1) * n],
            *th,
        );
        let ratio = (res / anorm - 2.0 * udd) / (20.0 * udd);
        eprintln!("dd eigs_near {c}: θ = {re:.6} {im:+.6}i, residual ratio {ratio:.3}");
        assert!(ratio <= C_K_DD, "{ratio}");
    }
    // The conjugate pairs keep the `+i` member first (Algorithm SG6).
    for w in f.values.windows(2) {
        assert!(w[0].im >= Dd::ZERO || w[1].im != -w[0].im, "{:?}", f.values);
    }
}

/// The acceptance of `eigsh_near` (criteria (a), (b), (c)) with `K =
/// FaerDense` (feature `faer`) as the dense kernel of the supernodal
/// `LBLᵀ` of `SymShiftInvert` (issue xingo-statla#7): built directly,
/// `eigsh` on it, `λ = σ + 1/ν`; the values also agree with those of the
/// reference kernel (`eigsh_near`) to `10⁻¹²‖A‖`.
#[cfg(feature = "faer")]
#[test]
fn eigsh_near_with_the_faer_kernel_matches_arpack() {
    use xingo_statla::SymShiftInvert;
    let u = f64::EPSILON / 2.0;
    let tau = f64::EPSILON;
    for name in SYM {
        let a = read_mm(name).a;
        let r = Ref::read(name);
        let n = a.n_rows();
        let anorm = r.values("norm2").unwrap()[0];
        let dense = r.values("dense").unwrap();
        let spec: Vec<(f64, f64)> = dense.iter().map(|&x| (x, 0.0)).collect();
        for (tag, k, vals) in r.tagged("eigsh_near") {
            let sigma: f64 = tag.parse().unwrap();
            let mut op = SymShiftInvert::<f64, _>::new(&a, sigma, xingo_sparse::FaerDense).unwrap();
            // (c).
            assert_eq!(
                op.count_below(),
                dense.iter().filter(|&&x| x < sigma).count(),
                "{name} σ = {sigma}"
            );
            let mut f =
                eigsh(&mut op, k, Which::LargestMagnitude, &EigsOptions::default()).unwrap();
            for v in &mut f.values {
                *v = sigma + 1.0 / *v;
            }
            let ours: Vec<Complex<f64>> =
                f.values.iter().map(|&re| Complex { re, im: 0.0 }).collect();
            let arp: Vec<(f64, f64)> = vals.iter().map(|&x| (x, 0.0)).collect();
            let cmp = compare(
                &ours,
                &arp,
                &spec,
                anorm,
                &format!("{name} faer near {sigma}"),
            );
            let (reference, _) = eigsh_near(&a, k, sigma, &EigsOptions::default()).unwrap();
            let y = f.vectors.as_ref().unwrap();
            let mut worst = 0.0f64;
            for (c, &th) in f.values.iter().enumerate() {
                assert!(
                    (th - reference.values[c]).abs() <= 1e-12 * anorm,
                    "{name} σ = {sigma}: faer {th} vs reference {}",
                    reference.values[c]
                );
                let rr = residual(
                    &a,
                    &y.data[c * n..(c + 1) * n],
                    &vec![0.0; n],
                    Complex { re: th, im: 0.0 },
                );
                let ratio = (rr / anorm - tau) / (default_ncv(n, k) as f64 * u);
                assert!(ratio <= C_K, "{name} faer near {sigma} {c}: ratio {ratio}");
                worst = worst.max(ratio);
            }
            print_row(
                name,
                &format!("eigsh_near σ={sigma}, K = FaerDense"),
                cmp,
                worst,
                f.stats.restarts,
                f.stats.applies,
                0.0,
            );
        }
    }
}

// ------------------------------------------------- the large fixtures

/// A CSC matrix from `(row, col, value)` triplets (distinct positions).
fn from_triplets(n: usize, mut t: Vec<(usize, usize, f64)>) -> CscMatrix<f64> {
    t.sort_by_key(|&(i, j, _)| (j, i));
    let mut col_ptr = vec![0usize; n + 1];
    for &(_, j, _) in &t {
        col_ptr[j + 1] += 1;
    }
    for j in 0..n {
        col_ptr[j + 1] += col_ptr[j];
    }
    CscMatrix {
        n_rows: n,
        col_ptr,
        row_idx: t.iter().map(|&(i, _, _)| i as u32).collect(),
        val: t.iter().map(|&(_, _, v)| v).collect(),
    }
}

/// `convdiff(nx, ny, px, py)` of `make_fixtures.py`, entry for entry
/// (`lap2d` is `px = py = 0`): `kron(I, tx) + kron(ty, I)`, `tx =
/// tridiag(−1 − px, 2, −1 + px)` (subdiagonal first), grid index `ix + nx
/// iy`. The diagonal is `2 + 2`; no other position receives two terms.
fn grid(nx: usize, ny: usize, px: f64, py: f64) -> CscMatrix<f64> {
    let mut t = Vec::new();
    for iy in 0..ny {
        for ix in 0..nx {
            let p = ix + nx * iy;
            t.push((p, p, 2.0 + 2.0));
            if ix + 1 < nx {
                t.push((p + 1, p, -1.0 - px));
                t.push((p, p + 1, -1.0 + px));
            }
            if iy + 1 < ny {
                t.push((p + nx, p, -1.0 - py));
                t.push((p, p + nx, -1.0 + py));
            }
        }
    }
    from_triplets(nx * ny, t)
}

/// `tridiag_graded(n)` of `make_fixtures.py`: `tridiag(−1, 2 + i/50, −1)`.
fn tridiag_graded(n: usize) -> CscMatrix<f64> {
    let mut t = Vec::new();
    for i in 0..n {
        t.push((i, i, 2.0 + i as f64 / 50.0));
        if i + 1 < n {
            t.push((i + 1, i, -1.0));
            t.push((i, i + 1, -1.0));
        }
    }
    from_triplets(n, t)
}

/// The matrix of a large fixture, checked against its `checksum` record
/// (`Σ a_ij (i + 1)(2j + 1)`, exactly rounded by the script; here summed
/// in double-double).
fn large(name: &str) -> (CscMatrix<f64>, Ref) {
    let a = match name {
        "lap2d_60x50" => grid(60, 50, 0.0, 0.0),
        "tridiag_graded_4000" => tridiag_graded(4000),
        "convdiff_60x50" => grid(60, 50, 0.1, 0.05),
        _ => unreachable!("{name}"),
    };
    let r = Ref::read(name);
    let mut s = Dd::ZERO;
    for j in 0..a.n_cols() {
        let (rows, vals) = a.col(Col::from_usize(j));
        for (&i, &v) in rows.iter().zip(vals) {
            s += Dd::from_f64(v) * Dd::from_f64((f64::from(i) + 1.0) * (2.0 * j as f64 + 1.0));
        }
    }
    let want = r.values("checksum").unwrap()[0];
    assert!(
        (s.to_f64() - want).abs() <= 1e-15 * want.abs(),
        "{name}: rebuilt matrix differs (checksum {} vs {want})",
        s.to_f64()
    );
    (a, r)
}

/// (a), (b), (c) of `eigsh_matches_arpack` on the symmetric large fixtures
/// (`n` = 3000 and 4000; issue xingo-statla#2), ignored for their cost.
#[test]
#[cfg_attr(
    debug_assertions,
    ignore = "large fixtures (n = 3000, 4000; 3 s in release): run with --ignored"
)]
fn eigsh_matches_arpack_large() {
    let u = f64::EPSILON / 2.0;
    let tau = f64::EPSILON;
    for name in ["lap2d_60x50", "tridiag_graded_4000"] {
        let (a, r) = large(name);
        let n = a.n_rows();
        let anorm = r.values("norm2").unwrap()[0];
        let near = r.values("dense_near").unwrap();
        let spec: Vec<(f64, f64)> = near.iter().map(|&x| (x, 0.0)).collect();
        let check = |vals: &[f64], y: &xingo_statla::DenseBlock<f64>, ncv: usize, what: &str| {
            let mut w = 0.0f64;
            for (c, &th) in vals.iter().enumerate() {
                let res = residual(
                    &a,
                    &y.data[c * n..(c + 1) * n],
                    &vec![0.0; n],
                    Complex { re: th, im: 0.0 },
                );
                let ratio = (res / anorm - tau) / (ncv as f64 * u);
                assert!(ratio <= C_K, "{name} {what} {c}: ratio {ratio}");
                w = w.max(ratio);
            }
            w
        };
        for (tag, k, vals) in r.tagged("eigsh") {
            let t0 = Instant::now();
            let f = eigsh(
                &mut a.clone(),
                k,
                Which::from_arpack(&tag).unwrap(),
                &EigsOptions::default(),
            )
            .unwrap();
            let ms = t0.elapsed().as_secs_f64() * 1e3;
            let ours: Vec<Complex<f64>> =
                f.values.iter().map(|&re| Complex { re, im: 0.0 }).collect();
            let arp: Vec<(f64, f64)> = vals.iter().map(|&x| (x, 0.0)).collect();
            let cmp = compare(&ours, &arp, &spec, anorm, &format!("{name} eigsh {tag}"));
            let res = check(
                &f.values,
                f.vectors.as_ref().unwrap(),
                default_ncv(n, k),
                &tag,
            );
            print_row(
                name,
                &format!("eigsh {tag}"),
                cmp,
                res,
                f.stats.restarts,
                f.stats.applies,
                ms,
            );
        }
        let counts: Vec<(f64, usize)> = r.lines.iter().find(|l| l[0] == "count_below").unwrap()
            [1..]
            .iter()
            .map(|t| {
                let (s, c) = t.split_once(':').unwrap();
                (s.parse().unwrap(), c.parse().unwrap())
            })
            .collect();
        for (tag, k, vals) in r.tagged("eigsh_near") {
            let sigma: f64 = tag.parse().unwrap();
            let t0 = Instant::now();
            let (f, below) = eigsh_near(&a, k, sigma, &EigsOptions::default()).unwrap();
            let ms = t0.elapsed().as_secs_f64() * 1e3;
            let want = counts.iter().find(|c| c.0 == sigma).unwrap().1;
            assert_eq!(below, want, "{name} σ = {sigma}: count_below");
            let ours: Vec<Complex<f64>> =
                f.values.iter().map(|&re| Complex { re, im: 0.0 }).collect();
            let arp: Vec<(f64, f64)> = vals.iter().map(|&x| (x, 0.0)).collect();
            let cmp = compare(&ours, &arp, &spec, anorm, &format!("{name} near {sigma}"));
            let res = check(
                &f.values,
                f.vectors.as_ref().unwrap(),
                default_ncv(n, k),
                "near",
            );
            print_row(
                name,
                &format!("eigsh_near σ={sigma} (below {below})"),
                cmp,
                res,
                f.stats.restarts,
                f.stats.applies,
                ms,
            );
        }
    }
}

/// (a), (b) of `eigs_matches_arpack` on the general large fixture
/// (convection–diffusion on a 60 × 50 grid, `n = 3000`), ignored for its
/// cost.
#[test]
#[cfg_attr(
    debug_assertions,
    ignore = "large fixtures (n = 3000, 4000; 3 s in release): run with --ignored"
)]
fn eigs_matches_arpack_large() {
    let u = f64::EPSILON / 2.0;
    let tau = f64::EPSILON;
    let name = "convdiff_60x50";
    let (a, r) = large(name);
    let n = a.n_rows();
    let anorm = r.values("norm2").unwrap()[0];
    let (dre, dim) = (
        r.values("dense_near_re").unwrap(),
        r.values("dense_near_im").unwrap(),
    );
    let spec: Vec<(f64, f64)> = dre.iter().zip(&dim).map(|(&x, &y)| (x, y)).collect();
    let pairs = |v: &[f64]| -> Vec<(f64, f64)> { v.chunks(2).map(|c| (c[0], c[1])).collect() };
    let check = |f: &xingo_statla::Eigen<f64>, ncv: usize, what: &str| {
        let (yr, yi) = (
            f.vectors_re.as_ref().unwrap(),
            f.vectors_im.as_ref().unwrap(),
        );
        let mut w = 0.0f64;
        for (c, th) in f.values.iter().enumerate() {
            let res = residual(
                &a,
                &yr.data[c * n..(c + 1) * n],
                &yi.data[c * n..(c + 1) * n],
                *th,
            );
            let ratio = (res / anorm - tau) / (ncv as f64 * u);
            assert!(ratio <= C_K, "{name} {what} {c}: ratio {ratio}");
            w = w.max(ratio);
        }
        w
    };
    for (tag, k, vals) in r.tagged("eigs") {
        let t0 = Instant::now();
        let f = eigs(
            &mut a.clone(),
            k,
            Which::from_arpack(&tag).unwrap(),
            &EigsOptions::default(),
        )
        .unwrap();
        let ms = t0.elapsed().as_secs_f64() * 1e3;
        let cmp = compare(
            &f.values,
            &pairs(&vals),
            &spec,
            anorm,
            &format!("{name} eigs {tag}"),
        );
        let res = check(&f, default_ncv(n, k), &tag);
        print_row(
            name,
            &format!("eigs {tag}"),
            cmp,
            res,
            f.stats.restarts,
            f.stats.applies,
            ms,
        );
    }
    for (tag, k, vals) in r.tagged("eigs_near") {
        let sigma: f64 = tag.parse().unwrap();
        let t0 = Instant::now();
        let f = eigs_near(&a, k, sigma, &EigsOptions::default()).unwrap();
        let ms = t0.elapsed().as_secs_f64() * 1e3;
        let cmp = compare(
            &f.values,
            &pairs(&vals),
            &spec,
            anorm,
            &format!("{name} near {sigma}"),
        );
        let res = check(&f, default_ncv(n, k), "near");
        print_row(
            name,
            &format!("eigs_near σ={sigma}"),
            cmp,
            res,
            f.stats.restarts,
            f.stats.applies,
            ms,
        );
    }
}

/// (d) of `svds_matches_scipy` on the three large fixtures, the gaps from
/// the `2K` largest dense singular values; ignored for its cost.
#[test]
#[cfg_attr(
    debug_assertions,
    ignore = "large fixtures (n = 3000, 4000; 3 s in release): run with --ignored"
)]
fn svds_matches_scipy_large() {
    for name in ["lap2d_60x50", "tridiag_graded_4000", "convdiff_60x50"] {
        let (mut a, r) = large(name);
        let top = r.values("sv_top").unwrap();
        let s1 = top[0];
        let rec = r.values("svds").unwrap();
        let (k, sc) = (rec[0] as usize, rec[1..].to_vec());
        let t0 = Instant::now();
        let f = svds(&mut a, k, &SvdsOptions::default()).unwrap();
        let ms = t0.elapsed().as_secs_f64() * 1e3;
        let (mut worst, mut n_cmp) = (0.0f64, 0);
        for (i, (&ours, &theirs)) in f.s.iter().zip(&sc).enumerate() {
            let g = top
                .iter()
                .enumerate()
                .filter(|&(j, _)| j != i)
                .map(|(_, &s)| (s - top[i]).abs())
                .fold(f64::INFINITY, f64::min);
            if theirs >= 1e-3 * s1 && g >= GAP * s1 {
                let e = (ours - theirs).abs() / theirs;
                assert!(e <= REL, "{name} σ_{i}: {ours} vs {theirs}");
                worst = worst.max(e);
                n_cmp += 1;
            }
            assert!((ours - top[i]).abs() <= 1e-12 * s1, "{name} σ_{i} vs dense");
        }
        eprintln!(
            "| {name} | {worst:.1e} | {n_cmp}/{k} | restarts {} | {ms:.1} ms |",
            f.stats.restarts
        );
    }
}
